(function()
local b=bit32 or bit
if not b then error("bit32 not found")end
local k={9,99,180,92,201,23,228,253,50,134,211,48,142,202,59,46}
local e=''
local function x(s,k)
local r={}
for i=1,#s do
local kb=k[(i-1)%#k+1]
table.insert(r,b.bxor(string.byte(s,i),kb))
end
return r
end
local function b64(d)
local c='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local s=''
d=d:gsub('[^'..c..'=]','')
d:gsub('.',function(x)
if x=='='then return''end
local r,f='',(c:find(x)-1)
for i=6,1,-1 do
r=r..(f%2^i-f%2^(i-1)>0 and'1'or'0')
end
return r
end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
if #x~=8 then return''end
local c=0
for i=1,8 do
c=c+(x:sub(i,i)=='1'and 2^(8-i)or 0)
end
s=s..string.char(c)
end)
return s
end
local dec=b64(e)
local bytes=x(dec,k)
local code=''
for i=1,#bytes do
code=code..string.char(bytes[i])
end
local f=loadstring or load
if not f then error("loadstring not found")end
local fn,err=f(code)
if not fn then error("Failed to load: "..tostring(err))end
fn()
end)()
